{
  "name": "@slkiser/opencode-quota",
  "version": "6.3.0",
  "packageManager": "pnpm@11.28.9",
  "description": "OpenCode quota & tokens usage with zero context window pollution. Supports GitHub Copilot, OpenAI (Plus/Pro), Google AGY, Z.ai coding plan and more.",
  "type": "module",
  "main": "./dist/index.js",
  "types": "./dist/index.d.ts",
  "bin": {
    "opencode-quota": "./dist/bin/opencode-quota.js"
  },
  "exports": {
    ".": {
      "types": "./dist/index.d.ts",
      "default": "./dist/index.js"
    },
    "./server": {
      "types": "./dist/index.d.ts",
      "default": "./dist/index.js"
    },
    "./tui": {
      "types": "./dist/tui.d.ts",
      "default": "./dist/tui.js"
    },
    "./gui-experimental": "./dist/gui-experimental.cjs"
  },
  "files": [
    "dist",
    "README.md",
    "LICENSE"
  ],
  "scripts": {
    "build": "node .github/scripts/clean-dist.mjs && tsc && tsc -p src/gui && node .github/scripts/copy-data.mjs && node .github/scripts/prepare-tui-dist.mjs && node .github/scripts/build-gui.mjs",
    "check": "vp check",
    "format": "vp fmt",
    "lint": "vp lint",
    "pack:release-package": "node .github/scripts/pack-release-package.mjs",
    "pricing:refresh": "node .github/scripts/refresh-modelsdev-pricing.mjs",
    "pricing:refresh:if-stale": "node .github/scripts/refresh-modelsdev-pricing-if-stale.mjs",
    "upstream:check": "node .github/scripts/check-upstream-plugin-updates.mjs",
    "upstream:prepare-review": "node .github/scripts/prepare-upstream-plugin-review.mjs",
    "upstream:sync": "node .github/scripts/sync-upstream-plugin-references.mjs",
    "release:check": "pnpm verify && pnpm run verify:release-version",
    "smoke:package": "node .github/scripts/smoke-packed-package.mjs",
    "verify:package-contents": "node .github/scripts/verify-package-contents.mjs",
    "verify:platform": "pnpm run build && pnpm test && pnpm run verify:package-contents",
    "verify:release-package": "node .github/scripts/verify-release-package.mjs",
    "verify:release-version": "node .github/scripts/verify-release-version.mjs",
    "verify:typescript-version": "node .github/scripts/verify-typescript-version.mjs",
    "verify:v4-history": "node .github/scripts/verify-v4-history.mjs",
    "typecheck": "tsc --noEmit",
    "test": "vp test run",
    "test:docs": "vp test run tests/contribution-guidance.test.ts tests/google-gemini-cli-org-only-docs.test.ts tests/quota-providers-docs-consistency.test.ts tests/readme-provider-ledger.test.ts",
    "test:watch": "vp test watch",
    "verify": "pnpm run check && pnpm run verify:typescript-version && pnpm run verify:v4-history && pnpm run verify:platform",
    "prepublishOnly": "pnpm run build",
    "prepare": "vp config --no-agent --hooks-dir .github/hooks"
  },
  "keywords": [
    "opencode",
    "plugin",
    "quota",
    "toast",
    "github",
    "copilot",
    "google",
    "gemini",
    "claude"
  ],
  "author": "",
  "license": "MIT",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/slkiser/opencode-quota.git"
  },
  "bugs": {
    "url": "https://github.com/slkiser/opencode-quota/issues"
  },
  "homepage": "https://github.com/slkiser/opencode-quota#readme",
  "devDependencies": {
    "@babel/core": "^7.29.7",
    "@babel/preset-typescript": "^7.29.7",
    "@opencode/plugin": "2.2.5",
    "@opentelemetry/sdk-metrics": "2.10.0",
    "@opentui/core": "^0.8.1",
    "@opentui/solid": "^0.8.1",
    "@types/node": "^22.20.5",
    "babel-preset-solid": "^1.9.12",
    "solid-js": "^1.9.12",
    "typescript": "7.0.2",
    "vite": "npm:@voidzero-dev/vite-plus-core@1.4.0",
    "vite-plugin-solid": "2.11.14",
    "vite-plus": "1.4.0",
    "yaml": "^2.9.1"
  },
  "dependencies": {
    "@opentelemetry/api": "~1.9.1",
    "jsonc-parser": "^3.3.1"
  },
  "peerDependencies": {
    "@opencode/plugin": ">=2.0.28",
    "@opentui/core": ">=0.5.17",
    "@opentui/solid": ">=0.5.17",
    "solid-js": ">=1.9.0"
  },
  "peerDependenciesMeta": {
    "@opentui/core": {
      "optional": true
    },
    "@opentui/solid": {
      "optional": true
    },
    "solid-js": {
      "optional": true
    }
  },
  "engines": {
    "node": "^22.13.0 || >=23.4.0"
  }
}

{
  "name": "cursor-opencode-provider",
  "version": "0.8.7",
  "description": "Use Cursor subscription models from OpenCode via Cursor's Connect-RPC agent protocol",
  "type": "module",
  "license": "MIT",
  "author": "oakimov",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/oakimov/cursor-opencode-provider.git"
  },
  "bugs": {
    "url": "https://github.com/oakimov/cursor-opencode-provider/issues"
  },
  "homepage": "https://github.com/oakimov/cursor-opencode-provider#readme",
  "keywords": [
    "opencode",
    "opencode-plugin",
    "cursor",
    "ai-sdk",
    "provider",
    "plugin"
  ],
  "main": "./dist/index.js",
  "types": "./dist/index.d.ts",
  "exports": {
    ".": {
      "types": "./dist/index.d.ts",
      "import": "./dist/index.js"
    },
    "./plugin": {
      "types": "./dist/plugin.d.ts",
      "import": "./dist/plugin.js"
    },
    "./plugin/v2": {
      "types": "./dist/plugin-v2.d.ts",
      "import": "./dist/plugin-v2.js"
    },
    "./plugin/opencode2": {
      "types": "./dist/plugin-opencode2.d.ts",
      "import": "./dist/plugin-opencode2.js"
    },
    "./server": {
      "types": "./dist/plugin-opencode2.d.ts",
      "import": "./dist/plugin-opencode2.js"
    },
    "./errors": {
      "types": "./dist/errors.d.ts",
      "import": "./dist/errors.js"
    },
    "./models": {
      "types": "./dist/models.d.ts",
      "import": "./dist/models.js"
    },
    "./pricing": {
      "types": "./dist/pricing.d.ts",
      "import": "./dist/pricing.js"
    },
    "./auth": {
      "types": "./dist/auth.d.ts",
      "import": "./dist/auth.js"
    },
    "./image-save": {
      "types": "./dist/image-save.d.ts",
      "import": "./dist/image-save.js"
    }
  },
  "files": [
    "dist",
    "LICENSE",
    "DISCLAIMER.md",
    "SECURITY.md",
    "README.md",
    "CHANGELOG.md"
  ],
  "scripts": {
    "build": "tsc",
    "typecheck": "tsc --noEmit && tsc --noEmit -p tsconfig.test.json",
    "test": "bun test",
    "test:coverage": "bun test --coverage --coverage-reporter=lcov && bun scripts/strip-copied-coverage.ts",
    "test:node-http2": "bun run build && node test/node-http2-cleanup.mjs && node test/node-http2-drain.mjs && node test/node-http2-session-memory.mjs",
    "test:watch": "bun test --watch",
    "generate:pricing": "bun run scripts/generate-cursor-pricing.ts",
    "generate:pricing:check": "bun run scripts/generate-cursor-pricing.ts -- --check",
    "check:pricing": "bun run scripts/check-cursor-pricing-coverage.ts",
    "live-test": "bash scripts/live-test.sh",
    "generate:images": "bun run scripts/probe-cursor-image-input.ts",
    "generate:images:check": "bun run scripts/probe-cursor-image-input.ts -- --check",
    "prepublishOnly": "bun run generate:pricing && bun run build"
  },
  "dependencies": {
    "@ai-sdk/provider": "3.0.15",
    "protobufjs": "^7.6.5"
  },
  "peerDependencies": {
    "@opencode-ai/plugin": "^1.17.13"
  },
  "peerDependenciesMeta": {
    "@opencode-ai/plugin": {
      "optional": true
    }
  },
  "devDependencies": {
    "@opencode-ai/plugin": "^1.18.16",
    "@tsconfig/node22": "^22.0.5",
    "@types/bun": "^1.3.0",
    "@types/node": "^22.20.1",
    "typescript": "^5.9.3"
  }
}

{
  "name": "opencode-gemini-auth",
  "version": "2.0.1",
  "author": "jenslys",
  "repository": "https://github.com/jenslys/opencode-gemini-auth",
  "main": "./dist/index.js",
  "module": "./dist/index.js",
  "types": "./dist/index.d.ts",
  "exports": {
    ".": {
      "types": "./dist/index.d.ts",
      "import": "./dist/index.js",
      "default": "./dist/index.js"
    },
    "./server": {
      "types": "./dist/server.d.ts",
      "import": "./dist/server.js",
      "default": "./dist/server.js"
    }
  },
  "files": [
    "dist",
    "README.md",
    "LICENSE"
  ],
  "license": "MIT",
  "type": "module",
  "scripts": {
    "build": "tsup",
    "smoke:node-import": "node -e \"Promise.all([import('opencode-gemini-auth'), import('opencode-gemini-auth/server')]).then(() => console.log('ok')).catch((error) => { console.error(error); process.exit(1); })\"",
    "prepack": "bun run build && bun run smoke:node-import",
    "prepublishOnly": "bun test && bun run prepack",
    "update:gemini-cli": "git -C .local/gemini-cli pull --ff-only",
    "update:gemini-cli-version": "node commands/sync-gemini-cli-version.mjs",
    "update:gemini-cli-sync": "npm run update:gemini-cli && npm run update:gemini-cli-version"
  },
  "devDependencies": {
    "@types/bun": "latest",
    "tsup": "^8.5.1",
    "typescript": "^5.9.3"
  },
  "dependencies": {
    "@opencode/plugin": "2.0.14",
    "@openauthjs/openauth": "^0.4.3"
  }
}
